(2007162, 275766, 47487, '<td valign="top">If I could see all three corners of the triangle, I might find the contrasting shapes more compelling. I like the reflections, though.</td>', 'If I could see all three corners of the triangle, I might find the contrasting shapes more compelling. I like the reflections, though.', '2006-01-05 13:55:10.000000', NULL, 1),
(2007163, 276266, 47487, '<td valign="top">Ooh, pretty color, and nice backlighting on the orange slice. Nicely focused and composed as well.</td>', 'Ooh, pretty color, and nice backlighting on the orange slice. Nicely focused and composed as well.', '2006-01-05 13:55:48.000000', NULL, 1),
(2007165, 274356, 38670, '<td valign="top">that picture is so outta focus. sorry its just a 3 for me. nothing artistic to it.</td>', 'that picture is so outta focus. sorry its just a 3 for me. nothing artistic to it.', '2006-01-05 13:56:13.000000', NULL, 1),
(2007168, 275217, 47487, '<td valign="top">Depth of field was just the TEENIEST bit too shallow here for my tastes; it would have been nicer with the whole subject (ornament) in focus. Good idea, and nice colors and composition, though.</td>', 'Depth of field was just the TEENIEST bit too shallow here for my tastes; it would have been nicer with the whole subject (ornament) in focus. Good idea, and nice colors and composition, though.', '2006-01-05 13:56:47.000000', NULL, 1),
