(2007237, 274868, 47487, '<td valign="top">Wow. Very sharp. I like this a lot.</td>', 'Wow. Very sharp. I like this a lot.', '2006-01-05 14:22:07.000000', NULL, 1),
(2007239, 275641, 47487, '<td valign="top">The object in the person''s hand is about the last thing my eyes settle on in this image. It''s a nice photograph of a person -- lots of life -- but for this particular challenge I think it falls a bit short. 5.</td>', 'The object in the person''s hand is about the last thing my eyes settle on in this image. It''s a nice photograph of a person -- lots of life -- but for this particular challenge I think it falls a bit short. 5.', '2006-01-05 14:23:05.000000', NULL, 1),
