INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(2009987, 274125, 44490, '<td valign="top">Nice blues - one of a different color would add some more interest.</td>', 'Nice blues - one of a different color would add some more interest.', '2006-01-06 13:34:52.000000', NULL, 1),
(2009993, 275930, 44490, '<td valign="top">Nice silhouette and composition, some crop would help, and wish for more size and detail.</td>', 'Nice silhouette and composition, some crop would help, and wish for more size and detail.', '2006-01-06 13:37:28.000000', NULL, 1),
(2009998, 276459, 44490, '<td valign="top">Nice colors and gelcaps with beads of medicine are interesting.  Would be better with either more distinct cap or no cap at all, and wish for more DOF and less out-of-focus foreground.</td>', 'Nice colors and gelcaps with beads of medicine are interesting.  Would be better with either more distinct cap or no cap at all, and wish for more DOF and less out-of-focus foreground.', '2006-01-06 13:39:52.000000', NULL, 1),
(2010001, 276475, 44490, '<td valign="top">Nice colors, wish for more DOF.</td>', 'Nice colors, wish for more DOF.', '2006-01-06 13:40:48.000000', NULL, 1),
(2010005, 275637, 44490, '<td valign="top">Nice shapes and shine, wish for a little more DOF.</td>', 'Nice shapes and shine, wish for a little more DOF.', '2006-01-06 13:41:49.000000', NULL, 1),
(2010011, 275633, 44490, '<td valign="top">Nice reflective shapes and composition, wish for more exposure/light/brightness and DOF with less out-of-focus foreground.</td>', 'Nice reflective shapes and composition, wish for more exposure/light/brightness and DOF with less out-of-focus foreground.', '2006-01-06 13:44:03.000000', NULL, 1),
(2010017, 275252, 44490, '<td valign="top">Nice capture, not-so-central-composition/crop and blurred background would be better.  I like the pose.</td>', 'Nice capture, not-so-central-composition/crop and blurred background would be better.  I like the pose.', '2006-01-06 13:46:34.000000', NULL, 1),
(2010019, 275996, 50530, '<td valign="top">very nice pic</td>', 'very nice pic', '2006-01-06 13:47:26.000000', NULL, 1),
(2010020, 273917, 44490, '<td valign="top">Nice trailing edge line and feathers, interesting shadow, and soft bokeh.  Too bad the eye is hidden.</td>', 'Nice trailing edge line and feathers, interesting shadow, and soft bokeh.  Too bad the eye is hidden.', '2006-01-06 13:49:05.000000', NULL, 1),
(2010024, 276013, 44490, '<td valign="top">Needs light on or around subject, not just blown-out screen.  Moving to get a silhouette of the drinker against the screen might have worked well.</td>', 'Needs light on or around subject, not just blown-out screen.  Moving to get a silhouette of the drinker against the screen might have worked well.', '2006-01-06 13:51:44.000000', NULL, 1),
(2010030, 275296, 44490, '<td valign="top">Nice lighting, color, and reflective base.  Not-so-central and not-so-side-on composition would be better.</td>', 'Nice lighting, color, and reflective base.  Not-so-central and not-so-side-on composition would be better.', '2006-01-06 13:54:36.000000', NULL, 1),
(2010056, 276428, 44490, '<td valign="top">Interesting guitar and nice colors.  Not-so-central and not-so-straight might be even more interesting.</td>', 'Interesting guitar and nice colors.  Not-so-central and not-so-straight might be even more interesting.', '2006-01-06 14:04:04.000000', NULL, 1),
(2010072, 276433, 44490, '<td valign="top">Nice composition and carved shapes in the board.  Might have been better reversed with white and more light in foreground and black and less light in background, as the black pieces seem to soak up the light, melt together, and loose definition.</td>', 'Nice composition and carved shapes in the board.  Might have been better reversed with white and more light in foreground and black and less light in background, as the black pieces seem to soak up the light, melt together, and loose definition.', '2006-01-06 14:10:19.000000', NULL, 1),
(2010077, 276473, 44490, '<td valign="top">Interesting shapes and nice blue colors.  Not-so-central and not-so-straight-on composition might be better.</td>', 'Interesting shapes and nice blue colors.  Not-so-central and not-so-straight-on composition might be better.', '2006-01-06 14:12:33.000000', NULL, 1),
(2010083, 274146, 38234, '<td valign="top">I like the idea and am a huge fan of natural shapes however, had this been a solitary tree the impact would have been greater, with all the other branches around fighting for attention this just doesn''t work as well as it could have</td>', 'I like the idea and am a huge fan of natural shapes however, had this been a solitary tree the impact would have been greater, with all the other branches around fighting for attention this just doesn''t work as well as it could have', '2006-01-06 14:14:55.000000', NULL, 1),
(2010088, 276359, 44490, '<td valign="top">Nice contrasts and shapes of ducks and waves.  Two eggs in the background don''t make up for the rest of the distracting background, cropping out background and bottom right would probably be better.</td>', 'Nice contrasts and shapes of ducks and waves.  Two eggs in the background don''t make up for the rest of the distracting background, cropping out background and bottom right would probably be better.', '2006-01-06 14:16:52.000000', NULL, 1),
(2010126, 275442, 44490, '<td valign="top">Nice sharpness, DOF, and composition, just wish for more brightness/white levels.</td>', 'Nice sharpness, DOF, and composition, just wish for more brightness/white levels.', '2006-01-06 14:30:14.000000', NULL, 1),
(2010171, 276459, 25754, '<td valign="top">I realize it might be intentional, but the light is a bit too hot to the top left. Although I generally love shallow DOF, in this case the DOF towards the front is distracting. Nice arrangement and subject!</td>', 'I realize it might be intentional, but the light is a bit too hot to the top left. Although I generally love shallow DOF, in this case the DOF towards the front is distracting. Nice arrangement and subject!', '2006-01-06 14:42:31.000000', NULL, 1),
(2010182, 276186, 25754, '<td valign="top">I love this idea! Very creative.</td>', 'I love this idea! Very creative.', '2006-01-06 14:46:07.000000', NULL, 1),
(2010186, 273696, 50103, '<td valign="top">Maybe I''m missing something, but I don''t get the face in the photo.  Also you can see a light in her hair.</td>', 'Maybe I''m missing something, but I don''t get the face in the photo.  Also you can see a light in her hair.', '2006-01-06 14:46:32.000000', NULL, 1),
(2010187, 273800, 44490, '<td valign="top">Nice lighting for golden light transmission in the clear pieces.  Wish for more light/brightness, either fewer pieces or else a touch more DOF, and a board position that doesn''t yell "suicide king" even to novice chess players.</td>', 'Nice lighting for golden light transmission in the clear pieces.  Wish for more light/brightness, either fewer pieces or else a touch more DOF, and a board position that doesn''t yell "suicide king" even to novice chess players.', '2006-01-06 14:46:37.000000', NULL, 1),
(2010214, 275640, 25754, '<td valign="top">hahahaha now that''s funny :)<br/>I love the concept and humour. Technically, this is looking a bit too blue on my monitor and focus could be better.</td>', 'hahahaha now that''s funny :)I love the concept and humour. Technically, this is looking a bit too blue on my monitor and focus could be better.', '2006-01-06 14:56:58.000000', NULL, 1),
(2010217, 274199, 25754, '<td valign="top">Neat! Great light and lovely blues.</td>', 'Neat! Great light and lovely blues.', '2006-01-06 14:58:02.000000', NULL, 1),
(2010246, 275923, 44490, '<td valign="top">Beautiful transparency, shapes, and colors.  Wish for more sharpness and DOF if possible.</td>', 'Beautiful transparency, shapes, and colors.  Wish for more sharpness and DOF if possible.', '2006-01-06 15:04:25.000000', NULL, 1),
(2010257, 274331, 44490, '<td valign="top">Nice foreground sharpness and appropriate DOF, thank you!  Not-so-straight-on composition would probably be more interesting.</td>', 'Nice foreground sharpness and appropriate DOF, thank you!  Not-so-straight-on composition would probably be more interesting.', '2006-01-06 15:06:53.000000', NULL, 1),
(2010271, 275446, 25754, '<td valign="top">Or crunch them very fast? I get the feeling you''re Canadian :)<br/>Love the colours. Could use some more DOF.</td>', 'Or crunch them very fast? I get the feeling you''re Canadian :)Love the colours. Could use some more DOF.', '2006-01-06 15:09:47.000000', NULL, 1),
(2010274, 276208, 44490, '<td valign="top">Nice sharpness and composition.  More brightness / white level might help reduce the feeling of the blue being overdone.</td>', 'Nice sharpness and composition.  More brightness / white level might help reduce the feeling of the blue being overdone.', '2006-01-06 15:10:21.000000', NULL, 1),
(2010295, 275707, 25754, '<td valign="top">love that curve along the top. nice lighting and composition. would have preferred to see it at the full 640 instead of 450 though :)</td>', 'love that curve along the top. nice lighting and composition. would have preferred to see it at the full 640 instead of 450 though :)', '2006-01-06 15:16:44.000000', NULL, 1),
(2010324, 276038, 50438, '<td valign="top">I really love the colors in this photo.  Composition is OK, but I think you could have twisted yourself and got a more interesting perspective, which would lend more towards the subject of this challenge.  But overall, great shot.</td>', 'I really love the colors in this photo.  Composition is OK, but I think you could have twisted yourself and got a more interesting perspective, which would lend more towards the subject of this challenge.  But overall, great shot.', '2006-01-06 15:24:44.000000', NULL, 1),
(2010333, 273731, 50438, '<td valign="top">very interesting photo, and interesting shape! What is it?!! I find the green part on the right a bit distracting though.</td>', 'very interesting photo, and interesting shape! What is it?!! I find the green part on the right a bit distracting though.', '2006-01-06 15:26:51.000000', NULL, 1),
(2010334, 275152, 50438, '<td valign="top">Awesome!  And great imagination.  I definitely see the dragon!</td>', 'Awesome!  And great imagination.  I definitely see the dragon!', '2006-01-06 15:27:38.000000', NULL, 1),
(2010349, 273669, 50438, '<td valign="top">wow! This one is great.  Make sure you offer a print for this one as I''m sure it''ll sell.  Great composition, very simple, and imaginative.  Great shot!</td>', 'wow! This one is great.  Make sure you offer a print for this one as I''m sure it''ll sell.  Great composition, very simple, and imaginative.  Great shot!', '2006-01-06 15:32:24.000000', NULL, 1),
(2010400, 274996, 46223, '<td valign="top">very interesting idea. Shadow is different from the form...</td>', 'very interesting idea. Shadow is different from the form...', '2006-01-06 15:49:49.000000', NULL, 1),
(2010405, 276449, 46223, '<td valign="top">if the name of the game would be pattern II - +2</td>', 'if the name of the game would be pattern II - +2', '2006-01-06 15:51:33.000000', NULL, 1),
